commands.command:
mysql -uroot -p"${DB_ROOT_PW}" -e "
CREATE DATABASE IF NOT EXISTS appdb;
CREATE TABLE IF NOT EXISTS appdb.customers (
  id INT PRIMARY KEY AUTO_INCREMENT,
  name VARCHAR(100),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
INSERT INTO appdb.customers (name) VALUES ('Alice'),('Bob'),('Carol'),('Dave'),('Eve');
SELECT COUNT(*) AS row_count FROM appdb.customers;
"
